/** 按厂商 key 渲染官方标志；未收录时返回 null */
export function BrandLogo({
  id,
  size = 24,
  className,
  style,
}: {
  id: string
  size?: number
  className?: string
  style?: React.CSSProperties
}) {
  const def = LOGOS[id]
  if (!def) return null
  return (
    <svg
      width={size}
      height={size}
      viewBox={def.viewBox}
      fill="currentColor"
      className={className}
      style={{ color: def.color, ...style }}
      aria-hidden="true"
    >
      {def.node}
    </svg>
  )
}

export const BRAND_LOGO_IDS: readonly string[] = Object.keys(LOGOS)

export function hasBrandLogo(id: string): boolean {
  return Object.prototype.hasOwnProperty.call(LOGOS, id)
}
